Here is the commit message:
usb: cdns3: gadget: fix NULL pointer dereference in ep_queue

When the gadget endpoint is disabled or not yet configured, the ep->desc
pointer can be NULL. This leads to a NULL pointer dereference when
__cdns3_gadget_ep_queue() is called, causing a kernel crash.

Add a check to return -ESHUTDOWN if ep->desc is NULL, which is the
standard return code for unconfigured endpoints.

This prevents potential crashes when ep_queue is called on endpoints
that are not ready.

Fixes: 7733f6c32e36 ("usb: cdns3: Add Cadence USB3 DRD Driver")
Cc: stable <stable@kernel.org>
Signed-off-by: Yongchao Wu <yongchao.wu@autochips.com>
Acked-by: Peter Chen <peter.chen@kernel.org>
Link: https://patch.msgid.link/20260331000407.613298-1-yongchao.wu@autochips.com
Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>

Here is the root cause:
The function `__cdns3_gadget_ep_queue` in the Cadence USB3 DRD driver does not check if `ep->desc` is NULL before using it. When the gadget endpoint is disabled or not configured, `ep->desc` is NULL, leading to a NULL pointer dereference and kernel crash. The missing validation allows invalid endpoint states to proceed, causing the bug.

Here is the patch:
  */
 static int __cdns3_gadget_ep_queue(struct usb_ep *ep,
 				   struct usb_request *request,
 				   gfp_t gfp_flags)
 {
 	struct cdns3_endpoint *priv_ep = ep_to_cdns3_ep(ep);
 	struct cdns3_device *priv_dev = priv_ep->cdns3_dev;
 	struct cdns3_request *priv_req;
 	int ret = 0;

+	if (!ep->desc)
+		return -ESHUTDOWN;
+
 	request->actual = 0;
 	request->status = -EINPROGRESS;
 	priv_req = to_cdns3_request(request);
 	trace_cdns3_ep_queue(priv_req);

 	if (priv_dev->dev_ver < DEV_VER_V2) {
 		ret = cdns3_wa2_gadget_ep_queue(priv_dev, priv_ep,
 						priv_req);

 		if (ret == EINPROGRESS)
 			return 0;
 	}

 	ret = cdns3_prepare_aligned_request_buf(priv_req);
 	if (ret < 0)
 		return ret;

 	if (likely(!(priv_req->flags & REQUEST_UNALIGNED))) {
 		ret = usb_gadget_map_request_by_dev(priv_dev->sysdev, request,
 					    usb_endpoint_dir_in(ep->desc));
 		if (ret)
 			return ret;
 	}

 	list_add_tail(&request->list, &priv_ep->deferred_req_list);

 	/*
 	 * For stream capable endpoint if prime irq flag is set then only start
 	 * request.
 	 * If hardware endpoint configuration has not been set yet then
 	 * just queue request in deferred list. Transfer will be started in
 	 * cdns3_set_hw_configuration.
 	 */
 	if (!request->stream_id) {
 		if (priv_dev->hw_configured_flag &&
 		    !(priv_ep->flags & EP_STALLED) &&
 		    !(priv_ep->flags & EP_STALL_PENDING))
 			cdns3_start_all_request(priv_dev, priv_ep);
 	} else {
 		if (priv_dev->hw_configured_flag && priv_ep->prime_flag)
 			cdns3_start_all_request(priv_dev, priv_ep);
 	}

 	return 0;
 }



